mapper.update:
update review
set reply_content = #{replyContent},
    reply_time = #{replyTime}
where id = #{id}

mapper.select:
select r.*, u.name as userName, u.avatar as userAvatar, coalesce(o.item_name, i.name) as itemName from review r left join user u on r.user_id = u.id left join explore_order o on r.order_id = o.id left join explore_item i on r.item_id = i.id
and ( o.item_name like concat('%',#{keyword},'%') or i.name like concat('%',#{keyword},'%') or u.name like concat('%',#{keyword},'%') or r.content like concat('%',#{keyword},'%') or r.reply_content like concat('%',#{keyword},'%') )
and r.item_id = #{itemId}
and r.user_id = #{userId}
and r.rating >= #{minRating}
and r.rating = #{rating}
and r.reply_content is not null and r.reply_content != ''
and (r.reply_content is null or r.reply_content = '')
order by r.create_time desc

select count(*) from review r left join user u on r.user_id = u.id
left join explore_order o on r.order_id = o.id left join explore_item i on r.item_id = i.id
r.id <= #{maxId}

select r.id, r.rating, r.content, r.reply_content, r.reply_time, r.create_time,
       u.name as user_name, coalesce(o.item_name, i.name) as item_name
from review r left join user u on r.user_id = u.id
left join explore_order o on r.order_id = o.id left join explore_item i on r.item_id = i.id

    r.id > #{lastId} and r.id <= #{snapshot.maxId}

        and (o.item_name like concat('%',#{snapshot.keyword},'%') or i.name like concat('%',#{snapshot.keyword},'%')
            or u.name like concat('%',#{snapshot.keyword},'%') or r.content like concat('%',#{snapshot.keyword},'%')
            or r.reply_content like concat('%',#{snapshot.keyword},'%'))

    and r.item_id = #{snapshot.itemId}
    and r.user_id = #{snapshot.userId}
    and r.rating >= #{snapshot.minRating}
    and r.rating = #{snapshot.rating}
    and r.reply_content is not null and r.reply_content != ''
    and (r.reply_content is null or r.reply_content = '')
    and r.create_time >= #{snapshot.startTime}
    and r.create_time <= #{snapshot.endTime}

order by r.id
limit #{limit}
